const KERN_PAIRS = [
  "AT70 AU12 AV49 AW22 AY74 Af23 At23 Av14 BT13 BV12 BX14 BY15 CT15 CY17",
  "DB23 DD23 DT29 DV15 DX24 DY28 DZ14 D.20 D,20 FA44 F.75 F,75 GT29 GV18",
